  function statusTimeline(current){var standard=["pending_review","reviewing","price_confirmed","awaiting_customer_confirmation","confirmed","ordered_from_supplier","arrived_at_warehouse","out_for_delivery","delivered"],terminal=["unavailable","cancelled"].indexOf(current)>-1,currentIndex=terminal?1:Math.max(0,standard.indexOf(current)),steps=terminal?["pending_review",current]:standard;return '<div class="request-timeline" data-status-timeline>'+steps.map(function(step,i){var done=i<currentIndex,currentStep=i===currentIndex;return '<div class="request-timeline__step '+(done?"is-done ":"")+(currentStep?"is-current":"")+'"><span class="request-timeline__dot">'+(done?C().icon("check"):i+1)+'</span><div><strong>'+statusLabel(step)+'</strong><p>'+(currentStep?t("orders.status"):"")+'</p></div></div>';}).join("")+'</div>';}
  function tracking(status,params){var request=params&&params.request?window.ELORA.store.getSubmittedSpecialRequest(params.request):null,trackedId=params&&params.order?String(params.order):"",trackedOrder=trackedId?(window.ELORA.store.getOrder(trackedId)||(D.orders||[]).find(function(order){return String(order.id)===trackedId;})):null;if(trackedOrder){var trackedStatus=trackedOrder.status||"pending_review",progress=trackedOrder.tracking!=null?Number(trackedOrder.tracking):trackedStatus==="delivered"?100:trackedStatus==="cancelled"?20:trackedStatus==="pending_review"?12:50,trackedItems=(trackedOrder.items||trackedOrder.products||[]).map(function(item){var id=item&&item.id!=null?item.id:item,p=window.ELORA.store.getProduct(id),quantity=item&&item.quantity||1;return p?'<div class="review-row"><span>'+C().escape(pick(p.name))+' × '+quantity+'</span><strong>'+C().money(p.price*quantity)+'</strong></div>':"";}).join("");return C().pageHero("ORDER "+C().escape(trackedOrder.id),t("orders.trackingTitle"),statusLabel(trackedStatus))+'<section class="section"><div class="container"><div class="state-board"><div class="tracking-head"><span class="status '+(trackedStatus==="delivered"?'status--success':trackedStatus==="cancelled"?'status--danger':'status--warning')+'">'+statusLabel(trackedStatus)+'</span><a class="btn btn--secondary" href="#/orders">'+t("account.orders")+'</a></div>'+(trackedItems?'<div class="checkout-review" style="margin-top:2rem">'+trackedItems+'</div>':"")+'<div class="progress" style="margin-top:2rem"><div class="progress__bar" style="--progress:'+Math.max(0,Math.min(100,progress))+'%"></div></div><div class="notice" style="margin-top:2rem">'+C().icon("info")+'<p>'+t("checkout.demoNotice")+'</p></div></div></div></section>';}if(request)return C().pageHero(t("shein.specialBadge"),t("orders.trackingTitle"),C().escape(request.productName||t("shein.fallbackName")))+'<section class="section"><div class="container"><div class="state-board"><div class="tracking-head"><span class="status status--warning">'+statusLabel(request.reviewStatus||"pending_review")+'</span><a class="btn btn--secondary" href="#/shein-request/'+encodeURIComponent(request.id)+'">'+t("common.viewDetails")+'</a></div>'+statusTimeline(request.reviewStatus||"pending_review")+'<div class="notice" style="margin-top:2rem">'+C().icon("info")+'<p>'+t("shein.pendingNotice")+'</p></div></div></div></section>';var title=status?t("orders."+status+"Title"):t("orders.trackingTitle"),body=status?"":t("orders.trackingBody"),steps=["confirmed","packed","shipped","delivered"],dates=["2026-07-29","2026-07-30","2026-07-31","2026-08-01"];return C().pageHero("ORDER EL-10516",title,body)+'<section class="section"><div class="container"><div class="state-board"><div class="timeline">'+steps.map(function(step,i){var done=status==='cancelled'?i===0:status==='delayed'?i<3:i<3;return '<div class="timeline__step '+(done?'is-done':i===2?'is-current':'')+'"><span class="timeline__dot">'+(done?C().icon("check"):i+1)+'</span><div><strong>'+t("orders."+step)+'</strong><p>'+C().date(dates[i])+ '</p></div></div>';}).join("")+'</div><div class="progress" style="margin-top:3rem"><div class="progress__bar" style="--progress:'+(status==='cancelled'?'20':status==='delayed'?'58':'68')+'%"></div></div></div></div></section>';}
  function orderSummary(order){if(!order)return "";var products=(order.items||[]).map(function(item){var p=window.ELORA.store.getProduct(item.id);return p?'<li><span>'+C().escape(pick(p.name))+' × '+item.quantity+'</span><strong>'+C().money(p.price*item.quantity)+'</strong></li>':"";}).join(""),requests=(order.specialRequests||[]).map(function(item){return '<li class="is-special"><span>'+C().escape(item.productName||t("shein.fallbackName"))+' × '+item.quantity+'</span><span class="status status--warning">'+t("shein.pricePending")+'</span></li>';}).join("");return '<div class="confirmation-summary"><h2>'+t("orders.summary")+'</h2><ul>'+products+requests+'</ul>'+(requests?'<p>'+t("cart.excludesSpecial")+'</p>':"")+'</div>';}
