  function sheinRequestDetails(id){var item=window.ELORA.store.getSubmittedSpecialRequest(id)||window.ELORA.store.getCartItem(id);if(!item||item.type!=="shein_request")return stateView("404");var image=safeImage(item.image),status=item.reviewStatus||"pending_review",displayed=item.displayedPrice!=null&&item.displayedPrice!==""?item.displayedPrice+" "+C().escape(item.displayedCurrency||"EGP"):t("shein.notSet");return C().pageHero(t("shein.specialBadge"),t("shein.detailsTitle"),C().escape(item.productName||t("shein.fallbackName")))+'<section class="section section--tight"><div class="container request-detail-layout"><div class="request-detail-media">'+(image?'<img src="'+image+'" alt="'+t("shein.previewAlt")+'">':'<span>'+C().icon("image")+'</span>')+'</div><div class="card form-card stack"><span class="status status--warning">'+statusLabel(status)+'</span><dl class="detail-list"><div><dt>'+t("shein.color")+'</dt><dd>'+C().escape(item.color)+'</dd></div><div><dt>'+t("shein.size")+'</dt><dd>'+C().escape(item.size)+'</dd></div><div><dt>'+t("shein.sheinSizeText")+'</dt><dd>'+C().escape(item.sheinSizeText||t("shein.notSet"))+'</dd></div><div><dt>'+t("shein.quantity")+'</dt><dd>'+Number(item.quantity||1)+'</dd></div><div><dt>'+t("shein.displayedPriceLabel")+'</dt><dd>'+displayed+'</dd></div><div><dt>'+t("shein.finalPrice")+'</dt><dd>'+(item.finalPrice!=null?C().money(item.finalPrice):t("shein.pricePending"))+'</dd></div><div><dt>'+t("shein.availability")+'</dt><dd>'+t(item.availability==="pending"?"shein.availabilityPending":"orders."+item.availability)+'</dd></div><div><dt>'+t("shein.notes")+'</dt><dd>'+C().escape(item.notes||t("shein.notSet"))+'</dd></div></dl><a class="btn btn--secondary" href="'+C().escape(item.productUrl)+'" target="_blank" rel="noopener noreferrer">'+C().icon("external-link")+t("shein.openLink")+'</a></div><div class="state-board request-detail-timeline"><h2>'+t("orders.trackingTitle")+'</h2>'+statusTimeline(status)+'<p class="notice-text">'+t("shein.pendingNotice")+'</p></div></div></section>';}
  function returns(){return C().pageHero("ÉLORA CARE",t("returns.title"),t("returns.body"))+'<section class="section"><div class="container grid grid--3"><article class="card metric-card" data-reveal>'+C().icon("package-check")+'<h3 style="margin-top:1rem">'+t("returns.start")+'</h3><p style="margin:1rem 0">'+t("returns.body")+'</p><a class="btn btn--primary" href="#/returns/request">'+t("returns.start")+'</a></article><article class="card metric-card" data-reveal>'+C().icon("clock")+'<h3 style="margin-top:1rem">14 days</h3><p style="margin-top:1rem">'+t("returns.policy")+'</p></article><article class="card metric-card" data-reveal>'+C().icon("headphones")+'<h3 style="margin-top:1rem">ÉLORA CARE</h3><p style="margin-top:1rem">WhatsApp · Email</p></article></div></section>';}
