  function stateView(type){var map={loading:["loader","states.loadingTitle","states.loadingBody"],empty:["sparkles","states.emptyTitle","states.emptyBody"],offline:["wifi-off","states.offlineTitle","states.offlineBody"],"404":["map","states.notFoundTitle","states.notFoundBody"],success:["check","states.successTitle","states.successBody"],error:["triangle-alert","states.errorTitle","states.errorBody"],"reset-success":["key-round","auth.resetSuccessTitle","auth.resetSuccessBody"],"login-error":["circle-alert","auth.loginError","auth.loginBody"],"otp-invalid":["shield-alert","auth.otpInvalid","auth.otpBody"],"otp-expired":["clock-alert","auth.otpExpired","auth.otpBody"],"returns-submitted":["check","returns.submittedTitle","returns.submittedBody"],"returns-empty":["package-open","returns.emptyTitle","returns.emptyBody"],"returns-accepted":["package-check","returns.acceptedTitle","returns.acceptedBody"],"returns-rejected":["package-x","returns.rejectedTitle","returns.rejectedBody"],"returns-refund":["refresh-cw","returns.refundTitle","returns.refundBody"]},c=map[type]||map.error;if(type==='loading')return C().pageHero("ÉLORA",t(c[1]),t(c[2]))+'<section class="section"><div class="container grid grid--3">'+[1,2,3].map(function(){return '<div class="skeleton skeleton-card"><div class="skeleton-line"></div><div class="skeleton-line"></div><div class="skeleton-line"></div></div>';}).join("")+'</div></section>';return '<section class="section"><div class="container">'+C().emptyState(c[0],t(c[1]),t(c[2]),type==='404'||type==='empty'?t("common.shopNow"):t("common.retry"),type==='404'||type==='empty'?"#/shop":"#/home")+'</div></section>';}
